ALTER TABLE public.products ADD COLUMN compare_at_price numeric, ADD COLUMN made_to_order boolean NOT NULL DEFAULT false, ADD COLUMN lead_time_days integer;
ALTER TABLE public.products ADD CONSTRAINT products_compare_at_price_nonnegative CHECK (compare_at_price IS NULL OR compare_at_price >= 0), ADD CONSTRAINT products_lead_time_positive CHECK (lead_time_days IS NULL OR lead_time_days > 0);
DO $$ DECLARE fn text; name text; BEGIN FOREACH name IN ARRAY ARRAY['get_public_store_products','get_public_store_product'] LOOP SELECT pg_get_functiondef(oid) INTO fn FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname=name; IF fn IS NULL THEN RAISE EXCEPTION 'Missing public catalog function %', name; END IF; fn := replace(fn, '''price'', p.price,', '''price'', p.price, ''compare_at_price'', p.compare_at_price, ''made_to_order'', p.made_to_order, ''lead_time_days'', p.lead_time_days,'); EXECUTE fn; END LOOP; END $$;
